import spinal.core._
class SeededAlu extends Component {
  val io = new Bundle {
    val a, b = in UInt(32 bits)
    val result = out UInt(32 bits)
    val ready = out Bool()
  }
  io.ready := True
  io.result := (io.a - io.b).resize(32)
}

